// PS Orbit Studio — Deterministic Lead Normalizer & Triage Scorer
const items = $input.all();
const output = [];

for (const item of items) {
  const raw = item.json.body || item.json;

  // 1. Phone Normalization (E.164 formatting for US numbers)
  let cleanPhone = (raw.buyer?.phone || '').replace(/\D/g, '');
  if (cleanPhone.length === 10) {
    cleanPhone = '+1' + cleanPhone;
  } else if (cleanPhone.length === 11 && cleanPhone.startsWith('1')) {
    cleanPhone = '+' + cleanPhone;
  } else {
    cleanPhone = raw.buyer?.phone || 'INVALID_PHONE';
  }

  // 2. Deterministic Intent & Urgency Scoring (Scale: 1 to 10)
  let score = 0;
  const reasons = [];

  // Timeline Evaluation
  const timeline = (raw.inquiry?.timeline || '').toLowerCase();
  if (timeline.includes('immediate') || timeline.includes('0-30')) {
    score += 4;
    reasons.push('Immediate purchase timeline (+4)');
  } else if (timeline.includes('1-3 months') || timeline.includes('60')) {
    score += 2;
    reasons.push('Short-term purchase timeline (+2)');
  } else {
    score += 1;
    reasons.push('Exploratory timeline (+1)');
  }

  // Financing / Capital Readiness
  const financing = (raw.inquiry?.financing || '').toLowerCase();
  if (financing.includes('cash')) {
    score += 4;
    reasons.push('All-cash buyer (+4)');
  } else if (financing.includes('pre-approved') || financing.includes('approved')) {
    score += 3;
    reasons.push('Pre-approved mortgage (+3)');
  } else {
    score += 1;
    reasons.push('Unverified financing (+1)');
  }

  // Budget Tier Evaluation
  const budget = Number(raw.inquiry?.budget) || 0;
  if (budget >= 500000) {
    score += 2;
    reasons.push('High-bracket property budget (+2)');
  } else if (budget >= 300000) {
    score += 1;
    reasons.push('Mid-bracket property budget (+1)');
  }

  // Priority Tier Assignment
  let priority = 'STANDARD';
  if (score >= 8) {
    priority = 'HIGH_PRIORITY_HOT';
  } else if (score >= 5) {
    priority = 'WARM';
  }

  output.push({
    json: {
      lead_id: raw.lead_id || `lead_${Date.now()}`,
      normalized_at: new Date().toISOString(),
      source: raw.source || 'Direct Webhook',
      client: {
        full_name: `${(raw.buyer?.first_name || '').trim()} ${(raw.buyer?.last_name || '').trim()}`.trim(),
        first_name: raw.buyer?.first_name || '',
        last_name: raw.buyer?.last_name || '',
        email: (raw.buyer?.email || '').trim().toLowerCase(),
        phone: cleanPhone,
        is_phone_valid: cleanPhone.startsWith('+1') && cleanPhone.length === 12
      },
      property: {
        address: raw.inquiry?.property_address || 'Unspecified Address',
        budget: budget,
        formatted_budget: `$${budget.toLocaleString('en-US')}`,
        financing: raw.inquiry?.financing || 'Unknown',
        timeline: raw.inquiry?.timeline || 'Unknown'
      },
      triage: {
        qualification_score: score,
        priority: priority,
        audit_trail: reasons,
        requires_immediate_call: score >= 8
      },
      raw_notes: raw.inquiry?.message || ''
    }
  });
}

return output;

